import {a as request,e as errorText} from './subtitles-B9Oqyk03.js';
import {o as serviceOrigin} from './config-Br-iLGYJ.js';

function button(text,style='quiet'){const b=document.createElement('button');b.type='button';b.className=style;b.textContent=text;return b}
function dialog(title,width=560){const d=document.createElement('dialog');d.className='figma-dialog';d.style.width=width+'px';const head=document.createElement('header'),h=document.createElement('h2'),close=button('关闭');h.textContent=title;head.append(h,close);d.append(head);d.setAttribute('aria-labelledby',h.id='dialog-title-'+crypto.randomUUID());close.onclick=()=>d.close();document.body.append(d);d.addEventListener('close',()=>d.remove(),{once:true});return d}
function paragraph(text){const p=document.createElement('p');p.textContent=text;return p}
export function confirmAction(title,text,action='确认',danger=false){return new Promise(resolve=>{const d=dialog(title);d.append(paragraph(text));const row=document.createElement('div');row.className='dialog-actions';const cancel=button('取消','secondary'),ok=button(action,danger?'danger':'primary');let accepted=false;cancel.onclick=()=>d.close();ok.onclick=()=>{accepted=true;d.close()};row.append(cancel,ok);d.append(row);d.addEventListener('close',()=>resolve(accepted),{once:true});d.showModal();cancel.focus()})}
export function showRoleRequirements(role){const d=dialog('查看要求'),h=document.createElement('h3'),p=paragraph(role.prompt),done=button('知道了','primary');h.textContent=role.name;p.className='role-preview';done.onclick=()=>d.close();d.append(h,p,done);d.showModal()}

function field(form,title,type,value='',required=true){const l=document.createElement('label'),i=document.createElement('input');l.textContent=title;i.type=type;i.value=value;i.required=required;i.autocomplete=type==='password'?'new-password':'off';i.spellcheck=false;l.append(i);form.append(l);return i}
export function connectProvider(preset,onSaved){
 const d=dialog('填写连接信息'),form=document.createElement('form');form.autocomplete='off';d.append(paragraph('填写服务连接信息。密钥只保存在本机，测试时仅发送固定文本。'),form);
 const name=field(form,'服务商','text',preset.id==='custom'?'':preset.name),key=field(form,'API Key','password'),base=field(form,'服务地址','url',preset.baseUrl||''),model=field(form,'模型 ID','text',preset.id==='deepseek'?'deepseek-chat':'');name.maxLength=80;key.maxLength=5000;model.maxLength=200;base.maxLength=1500;
 const wrap=document.createElement('div');wrap.className='password';key.replaceWith(wrap);wrap.append(key);const reveal=button('显示');reveal.setAttribute('aria-label','显示 API Key');reveal.onclick=()=>{const visible=key.type==='password';key.type=visible?'text':'password';reveal.textContent=visible?'隐藏':'显示';reveal.setAttribute('aria-pressed',String(visible));reveal.setAttribute('aria-label',visible?'隐藏 API Key':'显示 API Key')};wrap.append(reveal);
 const pl=document.createElement('label'),protocol=document.createElement('select');pl.textContent='接口协议';for(const [value,label]of [['openai','OpenAI 兼容'],['anthropic','Claude / Messages'],['gemini','Gemini 原生']])protocol.add(new Option(label,value));protocol.value=preset.protocol||'openai';pl.append(protocol);if(preset.id==='custom')form.append(pl);
 const note=paragraph('测试会消耗少量模型额度；打开设置不会自动发送请求。'),status=paragraph(''),row=document.createElement('div'),cancel=button('取消','secondary'),test=button('测试连接','primary');note.className='dialog-message';status.className='dialog-message';status.setAttribute('role','status');status.setAttribute('aria-live','polite');row.className='dialog-actions';test.type='submit';row.append(cancel,test);form.append(note,status,row);cancel.onclick=()=>d.close();let proof,testing=false,revision=0;
 const values=()=>({provider:{name:name.value.trim(),baseUrl:base.value.trim(),models:[model.value.trim()],protocol:protocol.value,preset:preset.id},key:key.value});
 form.addEventListener('input',()=>{revision++;proof=undefined;test.textContent='测试连接';d.querySelector('h2').textContent='填写连接信息';status.textContent='';status.removeAttribute('data-tone')});
 form.onsubmit=async e=>{e.preventDefault();if(testing||!form.reportValidity())return;testing=true;const current=revision;test.disabled=true;form.setAttribute('aria-busy','true');try{const data=values();if(proof){test.textContent='正在保存…';const saved=await request({type:'SAVE_PROVIDER',...data,makeDefault:true,draftProof:proof});d.close();await onSaved(saved);return}d.querySelector('h2').textContent='正在测试';test.textContent='测试中…';status.textContent='正在连接服务并测试翻译，请稍候…';if(!await chrome.permissions.request({origins:[serviceOrigin(data.provider.baseUrl)]}))throw new Error('未获得模型地址访问权限，请允许后重试');const result=await request({type:'PROBE_DRAFT',...data});if(!d.open||current!==revision)return;proof=result.proof;d.querySelector('h2').textContent='连接成功';status.dataset.tone='success';status.textContent='连接测试成功。保存后即可在插件中使用此模型。';test.textContent='保存并使用'}catch(err){if(!d.open||current!==revision)return;proof=undefined;d.querySelector('h2').textContent='连接失败';status.dataset.tone='error';status.textContent=errorText(err);test.textContent='重试连接'}finally{testing=false;test.disabled=false;form.removeAttribute('aria-busy')}};
 d.showModal();(name.value?key:name).focus();
}

let batchHooks={};
function moveDisclosure(id,title,width=560){const section=document.getElementById(id);if(!section)return;const content=section.querySelector('.disclosure-content'),d=dialog(title,width),form=document.createElement('form'),row=document.createElement('div'),save=button(id==='connection-settings'?'保存并测试':'保存设置','primary'),cancel=button('取消','secondary');const snapshot=[...content.querySelectorAll('input,select,textarea')].map(el=>[el,el.value,el.checked]),primaryValue=document.getElementById('primary-model').value,batchSnapshot=id==='translation-settings'?batchHooks.get?.():undefined;section.open=false;row.className='dialog-actions';row.append(cancel,save);form.append(content,row);d.append(form);for(const el of content.querySelectorAll('input,select,textarea'))el.setAttribute('form','provider-form');
 const providerForm=document.getElementById('provider-form'),wasClean=document.getElementById('save').disabled;
 const relayInput=e=>providerForm.oninput?.(e),relayChange=()=>providerForm.dispatchEvent(new Event('change'));
 content.addEventListener('input',relayInput);content.addEventListener('change',relayChange);
 cancel.onclick=()=>d.close();let applied=false;d.addEventListener('close',()=>{content.removeEventListener('input',relayInput);content.removeEventListener('change',relayChange);if(!applied)for(const [el,value,checked]of snapshot){el.value=value;el.checked=checked}for(const el of content.querySelectorAll('[form]'))el.removeAttribute('form');section.append(content);if(!applied&&id==='translation-settings')batchHooks.restore?.(batchSnapshot);if(!applied&&id==='model-settings'){providerForm.oninput?.({target:document.getElementById('model')});document.getElementById('primary-model').value=primaryValue;providerForm.dispatchEvent(new Event('change'))}if(!applied&&wasClean)document.dispatchEvent(new Event('oneclear:restore-provider'))});
 const note=paragraph('');note.className='dialog-message';note.setAttribute('role','status');form.insertBefore(note,row);
 save.onclick=async()=>{if(![...content.querySelectorAll('input,select,textarea')].every(el=>el.reportValidity()))return;save.disabled=true;const providerForm=document.getElementById('provider-form');try{if(!providerForm.reportValidity())throw new Error('请先完整填写连接与模型信息');providerForm.requestSubmit(document.getElementById('save'));await new Promise((resolve,reject)=>{let ticks=0;const timer=setInterval(()=>{const msg=document.getElementById('form-message');if(++ticks>120){clearInterval(timer);reject(new Error('保存超时，请查看模型设置'))}else if(!providerForm.inert){clearInterval(timer);msg.dataset.tone==='error'&&msg.textContent?reject(new Error(msg.textContent)):resolve()}},100)});applied=true;d.close();if(id==='connection-settings')document.getElementById('probe').click()}catch(err){note.dataset.tone='error';note.textContent=errorText(err)}finally{save.disabled=false}};
 if(id==='translation-settings'){const l=document.createElement('div');l.textContent='每批段落数';const choice=document.createElement('div');choice.className='choice-row batch-choices';for(const n of[4,8,16]){const b=button(n+' 段');b.setAttribute('aria-pressed',String(+document.getElementById('batch-size').value===n));b.onclick=()=>{const input=document.getElementById('batch-size');input.value=n;input.dispatchEvent(new Event('input',{bubbles:true}));for(const item of choice.children)item.setAttribute('aria-pressed',String(item===b))};choice.append(b)}l.append(choice);form.prepend(l);const advanced=document.createElement('details'),summary=document.createElement('summary');summary.textContent='高级批量配置';form.insertBefore(advanced,content);advanced.append(summary,content)}
 if(id==='model-settings'){const defaultLabel=document.createElement('label'),defaultSelect=document.createElement('select'),originalSelect=document.getElementById('primary-model');defaultLabel.textContent='默认模型';for(const option of originalSelect.options)defaultSelect.add(new Option(option.text,option.value));defaultSelect.value=originalSelect.value;defaultSelect.onchange=()=>{originalSelect.value=defaultSelect.value;providerForm.oninput?.({target:originalSelect})};defaultLabel.append(defaultSelect);form.insertBefore(defaultLabel,content);const addLabel=document.createElement('label');addLabel.textContent='新增模型 ID';const input=document.createElement('input');input.placeholder='填写账号可用的模型 ID';input.maxLength=200;addLabel.append(input);const add=button('添加并设为默认','primary');add.onclick=()=>{const value=input.value.trim();if(!value)return;const ids=document.getElementById('model'),list=ids.value.split(/\s+/).filter(Boolean);ids.value=[value,...list.filter(x=>x!==value)].join('\n');ids.dispatchEvent(new Event('input',{bubbles:true}));const select=document.getElementById('primary-model');select.value=value;defaultSelect.replaceChildren(...[...select.options].map(option=>new Option(option.text,option.value)));defaultSelect.value=value;providerForm.oninput?.({target:select});input.value=''};form.insertBefore(addLabel,content);form.insertBefore(add,content)}
 d.showModal();
}
export function initFigmaSettings(hooks={}){batchHooks=hooks;for(const [id,title,width]of [['connection-settings','高级连接',560],['model-settings','管理可用模型',560],['translation-settings','批量翻译',480]]){document.querySelector('#'+id+'>summary')?.addEventListener('click',e=>{e.preventDefault();moveDisclosure(id,title,width)})}
 const cancel=document.createElement('button');cancel.id='cancel-role';cancel.type='button';cancel.className='secondary';cancel.textContent='取消';cancel.onclick=()=>document.getElementById('close-role').click();document.getElementById('role-form-actions').prepend(cancel);
 document.getElementById('role-form').addEventListener('invalid',e=>{e.target.setAttribute('aria-invalid','true');document.getElementById('role-form-message').textContent=document.getElementById('role-name').validity.valid?'请填写翻译要求。':'请填写角色名称。'},true);document.getElementById('role-form').addEventListener('input',e=>{e.target.removeAttribute('aria-invalid');document.getElementById('role-form-message').textContent=''});
}
export async function shortcutsHelp(){const d=dialog('修改快捷键');d.append(paragraph('快捷键由 Chrome 统一管理。在扩展快捷键页面找到「盐译」，设置翻译和显示模式的组合键。'));const code=document.createElement('code');code.textContent='chrome://extensions/shortcuts';const row=document.createElement('div'),open=button('打开快捷键设置','primary');row.className='dialog-actions';open.onclick=async()=>{try{await request({type:'OPEN_SHORTCUTS'});d.close()}catch(err){d.append(paragraph(errorText(err)))}};row.append(open);d.append(code,row);d.showModal()}
